insert into public.training_drills (is_template,title,category,difficulty,role_tags,duration_minutes,objective,setup,steps,success_criteria,scoring_rubric,tags,archived)
select true,v.title,v.category,v.difficulty,v.roles,v.duration,v.objective,v.setup,v.steps,v.success,'{}'::jsonb,v.tags,false
from (values
('Primary Entry Timing & Safe Exit','role','advanced',array['P1 Primary Rusher'],15,'Create a clean opening without overcommitting P1.','Custom room: P1 entry, P2 trade-ready; repeat controlled 2v2 engagements.',array['IGL gives target + timing cue.','P1 confirms and enters only on agreed cue.','P2 holds trade distance and calls contact.','P1 disengages if trade window is lost.','Reset and review entry timing.'],'Entry is synchronized; P1 is not isolated; disengage call is obeyed.',array['entry','trade','rusher']),
('P2 Trade Window & Pair Distance','backup','advanced',array['P2 Secondary Rusher'],15,'Convert P1 contact into a coordinated trade, not a delayed solo push.','2v2/4v4 custom; focus on line of sight and agreed push cue.',array['P2 states ready before P1 commits.','P1 calls contact and direction.','P2 acts inside the trade window.','Both call damage/knock and reset together.'],'P2 is ready before entry; no late uncoordinated push.',array['trade','backup','coordination']),
('P3 Flank Route & Timing Discipline','flank','advanced',array['P3 Third Rusher / Flanker'],20,'Apply flank pressure while preserving information and regroup options.','Custom room with marked primary fight and alternate flank route.',array['P3 reports route and ETA.','IGL approves flank timing.','P3 checks crossfire and escape path.','P3 calls pressure before contact.','Regroup on command if primary fight moves.'],'Flank timing is communicated; team retains a regroup path.',array['flank','information','positioning']),
('P4 Sniper Info & IGL Call Loop','igl','medium',array['P4 Sniper + IGL'],15,'Turn visual information into concise, executable team calls.','Squad custom; P4 observes and leads calls.',array['P4 reports enemy count, direction and distance.','IGL gives one action + timing + fallback.','Players repeat/acknowledge call.','P4 updates when information changes.'],'Calls are specific, acknowledged and updated; no contradictory calls.',array['igl','communication','macro']),
('Four-Player Focus Fire & Target Switch','squad-coordination','advanced',array['All players'],15,'Synchronize target priority and avoid split damage.','Custom room; one caller; practice 3 target switches.',array['Caller names target and direction.','All players confirm target.','Squad focuses until knock/retreat cue.','Caller announces switch; squad changes together.'],'At least 3 clean target switches with no split focus.',array['focus-fire','target-priority','teamwork']),
('Zone Edge Hold & Exit Route','rotation','advanced',array['P4 Sniper + IGL','All players'],20,'Prepare zone-edge hold with a clear exit and avoid panic rotation.','BR custom; practice safe route, cover and fallback.',array['IGL identifies next zone and route.','P3 checks flank/route information.','P4 covers approach and calls threats.','P1/P2 hold ready positions.','Rotate on trigger; regroup at checkpoint.'],'Rotation starts before pressure; all four reach checkpoint together.',array['zone','rotation','survival']),
('Endgame Cover Triangle','endgame','elite',array['All players'],20,'Create layered cover and controlled movement in final zones.','BR custom; 3–4 squad end-zone scenarios.',array['IGL assigns anchor, cover and move roles.','P4 calls threats and safe lanes.','P3 watches flank; P1/P2 move only on cue.','Squad preserves utility and cover.','Review position and exposure after each scenario.'],'No isolated movement; every move has cover and a fallback.',array['endgame','positioning','cover']),
('Comms Under Pressure: 3-Word Calls','communication','medium',array['All players'],10,'Keep combat comms short, relevant and actionable.','Timed custom fights; prohibit long explanations during action.',array['Use location + threat + action.','Avoid duplicate calls; one IGL decision voice.','Acknowledge orders with short confirmation.','Move analysis to post-fight review.'],'Critical info is timely; calls remain concise; IGL voice stays clear.',array['communication','igl','clarity'])
) as v(title,category,difficulty,roles,duration,objective,setup,steps,success,tags)
where not exists(select 1 from public.training_drills d where d.is_template=true and d.title=v.title);